update public.learning_paths
set
  title = 'Web / Interactive Design',
  goal = 'Web / Interactive Design',
  summary = 'Web / Interactive Design treats the web as a designed medium shaped by standards, screens, users, interaction, content, and changing device contexts. Students ground decisions in research and evidence, design findable structures and readable responsive screens, and learn enough HTML and CSS to prototype responsibly across devices, input modes, and interaction patterns. They practice wireframing, accessibility, motion, design systems, and UX writing, then evaluate and iterate with usability testing and analytics, examine AI and emerging interfaces, and synthesize the work in a polished responsive interactive product and portfolio case study.',
  data = $webinjson${"slug": "web-interactive-design", "title": "Web / Interactive Design", "description": "Web / Interactive Design treats the web as a designed medium shaped by standards, screens, users, interaction, content, and changing device contexts. Students ground decisions in research and evidence, design findable structures and readable responsive screens, and learn enough HTML and CSS to prototype responsibly across devices, input modes, and interaction patterns. They practice wireframing, accessibility, motion, design systems, and UX writing, then evaluate and iterate with usability testing and analytics, examine AI and emerging interfaces, and synthesize the work in a polished responsive interactive product and portfolio case study.", "topics": [{"id": "7b9f2dd2-bcc7-401b-8e0f-69752e8f9c14", "type": "topic", "title": "Web and Interactive Design Foundations", "description": "Students learn the web as a designed medium shaped by standards, screens, users, interaction, content, and changing device contexts.", "children": [{"id": "d52f98a9-66fa-40c8-95a8-998b787f388c", "type": "subtopic", "title": "The web as medium", "children": [{"id": "69dc3ce7-3b26-403f-be25-4877b5278dcd", "type": "concept", "title": "Websites, apps, services, platforms, interfaces, and digital products"}, {"id": "d2b883ca-985d-438c-b023-e327f01691a1", "type": "concept", "title": "Browsers, devices, viewports, networks, constraints, and progressive enhancement"}, {"id": "579ad392-7d67-4b4b-bfc8-2674f957792b", "type": "concept", "title": "Visual design, content, interaction, code, and usability as one ecosystem"}], "description": "This subtopic frames the web as a living, flexible, networked design environment rather than a fixed page."}, {"id": "cf5f5608-e54a-474b-9b19-a8b6c67f3bfd", "type": "subtopic", "title": "Interface purpose and product goals", "children": [{"id": "ec789cb2-0cfc-405a-8832-1c9e6482e641", "type": "concept", "title": "Audience, task, context, conversion, comprehension, trust, and retention"}, {"id": "b65ed783-a79c-4875-a1ad-caa8cf337982", "type": "concept", "title": "Product goals, service goals, brand goals, content goals, and accessibility goals"}, {"id": "ccb1d12a-70d6-45e6-b146-73ee32ed07b6", "type": "concept", "title": "Success metrics, failure modes, and design tradeoffs"}], "description": "Students learn to connect interface decisions to user needs and organizational goals."}, {"id": "0742aad1-286d-4cb6-8238-83e0f20c51dd", "type": "subtopic", "title": "Digital design process", "children": [{"id": "d9f67ffb-8f5c-47e8-8a41-94fc15b1d5cf", "type": "concept", "title": "Briefs, research, sketches, wireframes, prototypes, visual comps, handoff, and QA"}, {"id": "963e8388-7124-4634-a629-5220330e5f33", "type": "concept", "title": "Divergent exploration, convergence, critique, and iteration"}, {"id": "9c9c51ff-6120-4749-8a14-3ffadda71b7a", "type": "concept", "title": "Documentation, rationale, and portfolio case-study habits"}], "description": "This section introduces a repeatable process for discovery, design, prototype, test, build, and iterate."}]}, {"id": "72cbf949-dcfc-47bb-9ab4-82ca2d2617fe", "type": "topic", "title": "Human-Centered UX Research and Strategy", "description": "Students learn how to ground web design decisions in real users, contexts, constraints, and evidence.", "children": [{"id": "a6f7c4a7-58bc-4f2b-9878-d8ed623ff169", "type": "subtopic", "title": "UX research foundations", "children": [{"id": "bd22f759-f8a5-4fb7-82d4-383a6ba881f6", "type": "concept", "title": "Stakeholder interviews, user interviews, contextual inquiry, surveys, diary studies, and competitive review"}, {"id": "de3fb8c5-4eb0-42fe-b88e-4cd75abb35d7", "type": "concept", "title": "Research questions, recruiting, consent, sampling, and bias"}, {"id": "65bacd14-0ed4-4b40-bc82-6e1238799099", "type": "concept", "title": "Qualitative synthesis, themes, insights, opportunities, and assumptions"}], "description": "This subtopic helps students choose research methods appropriate to early-stage design questions."}, {"id": "c2631486-38a6-4d28-8690-6437e9bb9bd3", "type": "subtopic", "title": "Personas, scenarios, and journeys", "children": [{"id": "f574072a-0fec-4d4d-98b1-c04de0e52752", "type": "concept", "title": "Personas, proto-personas, empathy maps, scenarios, jobs-to-be-done, and needs statements"}, {"id": "8e0ae61e-8ee1-4d2e-b4fa-bd312ccb066c", "type": "concept", "title": "Journey maps, service moments, pain points, opportunities, and emotional arcs"}, {"id": "b4c91c0f-86f3-4ae0-8ed1-fbc01cbac850", "type": "concept", "title": "Research-backed artifacts versus decorative templates"}], "description": "Students translate research into practical design tools without turning people into stereotypes."}, {"id": "ee02a1b6-245c-4ce1-bad0-3cbd605ba54f", "type": "subtopic", "title": "Product and content strategy", "children": [{"id": "248ef4a3-ff8a-40b9-81e2-16787eed0be3", "type": "concept", "title": "Problem statements, value proposition, MVP scope, feature prioritization, and design principles"}, {"id": "f1c6c7de-3280-484b-800b-ba27fc73bd97", "type": "concept", "title": "Content goals, governance, SEO/findability, and conversion paths"}, {"id": "c199ad25-baa5-47b8-ab45-625f0dee4f5d", "type": "concept", "title": "Risk, constraints, stakeholder alignment, and measurable outcomes"}], "description": "This section connects user research to scope, prioritization, and strategic design choices."}]}, {"id": "a0fa428e-3a47-4f00-a002-2d9a3fc28e1a", "type": "topic", "title": "Information Architecture, Navigation, and Findability", "description": "Students design structures that help people locate, understand, and move through content and tasks.", "children": [{"id": "526c05fb-ac43-4e27-a2fa-b2b39ca54523", "type": "subtopic", "title": "Information architecture fundamentals", "children": [{"id": "f0c198b6-4644-48db-9935-b8c9987cadaf", "type": "concept", "title": "Sitemaps, taxonomies, labels, navigation models, metadata, and content models"}, {"id": "313e2f0f-8170-4017-ac76-76fe2dcf3232", "type": "concept", "title": "Hierarchy, sequence, grouping, hubs, landing pages, detail pages, and cross-links"}, {"id": "32cc6ffe-203a-4acf-b61d-2cd674af2abc", "type": "concept", "title": "Mental models, information scent, findability, and orientation"}], "description": "This subtopic explains how structure makes digital experiences understandable."}, {"id": "3a5a51a9-6565-4037-922e-6f0536a5d8d4", "type": "subtopic", "title": "Navigation and wayfinding", "children": [{"id": "fade2448-5e70-4389-a590-45721d643778", "type": "concept", "title": "Global, local, contextual, utility, footer, search, filters, breadcrumbs, and tabs"}, {"id": "b9602d35-e2e4-473f-b4af-b85838a7db38", "type": "concept", "title": "Menus, mega menus, cards, page titles, active states, and progress indicators"}, {"id": "bb489e70-4a66-4e0f-9a53-4444776e7a70", "type": "concept", "title": "Mobile navigation, disclosure patterns, and deep content structures"}], "description": "Students learn to design clear paths through complex digital environments."}, {"id": "a6d4887c-223e-4cf6-9a07-5ea009644e35", "type": "subtopic", "title": "IA testing and refinement", "children": [{"id": "40b42a68-1fa5-4feb-b7cc-4b81bdd960b7", "type": "concept", "title": "Card sorting, tree testing, first-click testing, search logs, analytics, and usability sessions"}, {"id": "03e5d2da-8f6c-43ce-bbd8-e2f895689ff3", "type": "concept", "title": "Label testing, taxonomy revisions, content gaps, and navigation debt"}, {"id": "597f0036-37ad-4b82-9905-e7fff85c7d90", "type": "concept", "title": "Balancing user language, organizational language, and SEO language"}], "description": "This section introduces evidence-based methods for improving structure."}]}, {"id": "a4eab89e-7f44-493f-b097-e5161f2e24a5", "type": "topic", "title": "Interface Layout, Visual Hierarchy, and Screen Typography", "description": "Students learn to compose screens that are readable, scannable, responsive, and visually coherent.", "children": [{"id": "166a7892-eec3-4d8b-9b4d-fe4b5e29d3b1", "type": "subtopic", "title": "Screen layout systems", "children": [{"id": "2d2d28de-78fd-4f38-875a-4f94f2315367", "type": "concept", "title": "Grids, columns, containers, spacing, cards, panels, breakpoints, and responsive regions"}, {"id": "6026d7d1-ed1e-4402-ae37-64eba577ced5", "type": "concept", "title": "Visual priority, reading paths, grouping, alignment, rhythm, and white space"}, {"id": "171a2911-235f-4200-827b-0af708004495", "type": "concept", "title": "Mobile-first layout, desktop complexity, and content reflow"}], "description": "This subtopic teaches students to make spatial decisions that scale across screens."}, {"id": "ff9e9039-622d-401d-ad4e-a764f6198463", "type": "subtopic", "title": "Typography for interfaces", "children": [{"id": "4745e436-ff23-4c38-9a4e-66fb1a984839", "type": "concept", "title": "Type scale, line height, measure, font pairing, labels, buttons, captions, forms, and error text"}, {"id": "fab6e32e-d76e-43b5-bbc8-485314fed6d7", "type": "concept", "title": "Legibility, contrast, variable fonts, localization, and responsive type"}, {"id": "016bc5f9-e4d2-43c9-b588-047a73ebfe90", "type": "concept", "title": "Typographic hierarchy, voice, density, and interface clarity"}], "description": "Students refine type choices for digital reading and task completion."}, {"id": "5385d88e-1108-43f7-8bbd-9bfe5899dcc0", "type": "subtopic", "title": "Visual design language", "children": [{"id": "6e283744-7f37-4bf7-99df-3c96111992f0", "type": "concept", "title": "Color systems, contrast, imagery, icon use, illustration, brand consistency, and affordance"}, {"id": "acb1a8a4-7294-404e-8a70-f4b6e426b3f5", "type": "concept", "title": "Visual noise, decorative overload, and clarity under constraint"}, {"id": "b9608a9c-e2c3-4b84-8efb-2cd3f5c874f9", "type": "concept", "title": "Designing for product credibility, emotion, and trust"}], "description": "This section integrates color, imagery, iconography, and brand into usable interfaces."}]}, {"id": "1d5c1faf-72c2-4985-b5fa-479485306d5e", "type": "topic", "title": "HTML, CSS, and Web Standards for Designers", "description": "Students learn enough front-end language to understand the medium, collaborate with developers, and prototype responsibly.", "children": [{"id": "6e8a8865-c10f-4c82-9dde-20e79beaa847", "type": "subtopic", "title": "Semantic HTML", "children": [{"id": "4809492c-72a0-4ad5-a9f5-1757f126fc11", "type": "concept", "title": "Headings, paragraphs, lists, links, images, buttons, forms, landmarks, and document outline"}, {"id": "87778dd6-6dbd-45cc-b2bb-932700457422", "type": "concept", "title": "Semantic elements, alt text, labels, tables, and ARIA as a last resort"}, {"id": "b5fcc1b3-15dc-4515-9da4-dca5c85e205d", "type": "concept", "title": "Source order, keyboard navigation, and screen-reader basics"}], "description": "This subtopic teaches students that structure matters for accessibility, SEO, maintainability, and meaning."}, {"id": "16148603-299d-4eaa-a97a-eab8d2d5a6fc", "type": "subtopic", "title": "CSS layout and styling", "children": [{"id": "eb660f3d-28ea-4d75-9f37-95df53fc2f79", "type": "concept", "title": "Box model, cascade, specificity, units, custom properties, typography, color, and spacing"}, {"id": "d14a02df-89c4-4ead-bbdb-3065fb0fdd5e", "type": "concept", "title": "Flexbox, grid, positioning, media queries, and responsive images"}, {"id": "27405cbb-d98a-4e7e-916e-93128a67c319", "type": "concept", "title": "Reusable classes, design tokens, and maintainable CSS patterns"}], "description": "Students learn the core styling concepts behind modern responsive interfaces."}, {"id": "1d6227ad-86a0-43c2-a3a2-1814b6cb3c63", "type": "subtopic", "title": "Web standards and performance awareness", "children": [{"id": "ada2d8d0-e816-45cf-8d1f-29f0003e789d", "type": "concept", "title": "Browser support, progressive enhancement, responsive assets, loading performance, and Core Web Vitals"}, {"id": "8c4145c9-4881-4f0c-91b2-7c69ab9cbef3", "type": "concept", "title": "File size, image formats, lazy loading, font loading, and motion preferences"}, {"id": "6841a692-a6ea-46c9-b162-c528da6724cf", "type": "concept", "title": "Developer handoff, inspection, QA, and basic debugging"}], "description": "This section helps designers understand constraints that affect real user experience."}]}, {"id": "859e943f-7bda-4764-a1cb-030eb578b8f4", "type": "topic", "title": "Responsive, Adaptive, and Mobile-First Design", "description": "Students design experiences that work across devices, contexts, input modes, and screen sizes.", "children": [{"id": "6c794c34-05cb-46b6-8688-2846a651bbe7", "type": "subtopic", "title": "Responsive design principles", "children": [{"id": "23a6ecdf-af8a-4716-a2c5-046f342a9dbc", "type": "concept", "title": "Fluid grids, flexible media, breakpoints, container thinking, and reflow"}, {"id": "e090ea2f-e33b-4325-8df8-4b1695d45775", "type": "concept", "title": "Mobile-first priorities, progressive disclosure, density shifts, and layout simplification"}, {"id": "d177b5b1-027a-4556-8b97-94481f337d98", "type": "concept", "title": "Testing across viewport sizes and real devices"}], "description": "This subtopic makes responsiveness a content and hierarchy problem, not just a resizing problem."}, {"id": "a6d00c25-cd7d-472d-86d3-9a55b78e7cae", "type": "subtopic", "title": "Input and device contexts", "children": [{"id": "2537574f-7160-4421-b21e-a8719e17fd84", "type": "concept", "title": "Touch targets, hover limits, gestures, keyboard focus, pointer types, and orientation"}, {"id": "6742bef2-3f5f-4ed7-a5d7-ce6dd141ee95", "type": "concept", "title": "Mobile constraints, desktop productivity, tablets, kiosks, and embedded web views"}, {"id": "b23697b1-0827-4f85-a329-257da6edd96b", "type": "concept", "title": "Context of use: on the go, low bandwidth, glare, interruptions, and accessibility tools"}], "description": "Students account for how interaction changes across touch, mouse, keyboard, and assistive technologies."}, {"id": "14cedd7a-c5ba-440d-8165-f46075145bf8", "type": "subtopic", "title": "Adaptive patterns and edge cases", "children": [{"id": "e4f7e5c5-894e-418b-855d-68a693b8e978", "type": "concept", "title": "Long names, missing images, empty states, error states, loading states, and localization"}, {"id": "813d11f0-b617-49e5-98d0-e9615775a1fe", "type": "concept", "title": "Dark mode, reduced motion, high contrast, offline states, and browser differences"}, {"id": "0ed0ab1e-9642-4cac-8240-c88dc6f9464c", "type": "concept", "title": "Responsive QA checklists and acceptance criteria"}], "description": "This section prepares students for messy real-world interface conditions."}]}, {"id": "25610fa9-ad3e-4545-9480-7fc473695e89", "type": "topic", "title": "Interaction Design Patterns and Interface Behavior", "description": "Students learn reusable interaction patterns and the reasoning behind them.", "children": [{"id": "68d83b74-fac6-4d88-8198-0910692b75ea", "type": "subtopic", "title": "Interaction patterns", "children": [{"id": "f8e8b634-3214-44d5-9f7c-01e01b2fed0e", "type": "concept", "title": "Forms, search, filters, sort, accordions, modals, tabs, menus, cards, carousels, and onboarding"}, {"id": "4b408a1b-ae9c-4dd2-9aba-c9353ef65c3b", "type": "concept", "title": "Selection, editing, confirmation, undo, save, share, compare, and checkout flows"}, {"id": "4687ea8c-1681-470d-ae41-e0836443ed0a", "type": "concept", "title": "Pattern benefits, risks, accessibility issues, and misuse"}], "description": "This subtopic introduces common patterns as tools to be chosen, adapted, and tested."}, {"id": "d2af5ac6-3e8d-4e4f-9d04-75575348eae0", "type": "subtopic", "title": "States, feedback, and affordances", "children": [{"id": "282e8283-d498-403c-99af-ac06ca6ec007", "type": "concept", "title": "Default, hover, active, focus, disabled, selected, loading, success, warning, and error states"}, {"id": "93d5fd0a-6af5-4257-a4e0-98b081cb226b", "type": "concept", "title": "Affordance, signifier, mapping, constraints, feedback, and mental models"}, {"id": "5cf3f057-1f78-4bb7-8264-1448ade39638", "type": "concept", "title": "Inline validation, progress indicators, notifications, and status messages"}], "description": "Students learn to make interfaces communicate what is possible and what just happened."}, {"id": "9875158b-1c64-4a1b-9e1e-eb66ae80a6fe", "type": "subtopic", "title": "Task flows and user control", "children": [{"id": "d44dffdb-01b8-41e8-a16b-ae41fbb65a6e", "type": "concept", "title": "Entry points, decision points, branching paths, recovery, undo, and exit paths"}, {"id": "e9a0d585-c888-457d-a733-0cf2768e6645", "type": "concept", "title": "Reducing friction without hiding consequences"}, {"id": "a3068c2d-bb67-485a-a303-b7e0a26ee955", "type": "concept", "title": "Designing for confidence, speed, reversibility, and comprehension"}], "description": "This section focuses on end-to-end interaction quality."}]}, {"id": "1c7b7522-794f-42d2-a9d3-fdb71e7beaf5", "type": "topic", "title": "Wireframing, Prototyping, and Figma Workflow", "description": "Students learn to make ideas testable through sketches, wireframes, clickable prototypes, and structured design files.", "children": [{"id": "be55ac54-556c-43e8-82aa-79999c798616", "type": "subtopic", "title": "Wireframing levels", "children": [{"id": "bab05fd3-05e2-4431-b437-7878805cc42d", "type": "concept", "title": "Sketches, low-fidelity wireframes, mid-fidelity flows, high-fidelity comps, and functional prototypes"}, {"id": "bc2d52c7-8abe-4d02-aa18-6cc3c24b75f2", "type": "concept", "title": "Content-first wireframes, annotation, layout exploration, and design constraints"}, {"id": "c8bef2ea-53ce-4a39-a328-95029ef416d1", "type": "concept", "title": "Avoiding premature visual polish when structure is unresolved"}], "description": "This subtopic clarifies what fidelity is appropriate at each design stage."}, {"id": "3722e2a7-0f14-4a0f-8b1c-e118fa2bf008", "type": "subtopic", "title": "Prototyping interactions", "children": [{"id": "330deeb9-45ef-459a-bc0a-1788d562d9d0", "type": "concept", "title": "Clickable flows, overlays, scroll behavior, variants, component states, and transitions"}, {"id": "7c5798cb-10fa-4add-877b-414663348d57", "type": "concept", "title": "Prototype scope, test tasks, success paths, and failure paths"}, {"id": "dfa079e8-a647-4a56-aa90-0aaf25f22aaa", "type": "concept", "title": "Figma, Sketch, web prototypes, and when code prototypes are better"}], "description": "Students create prototypes that support critique, testing, and stakeholder discussion."}, {"id": "5d4923c3-72e7-43be-9d65-148ad37683d5", "type": "subtopic", "title": "Design file hygiene", "children": [{"id": "4a8bc5bb-225c-4d84-96a3-84f7c71fc003", "type": "concept", "title": "Pages, frames, naming, auto layout, components, variants, styles, variables, and libraries"}, {"id": "64497eba-0d4b-40a3-ad22-2c344ec8bda2", "type": "concept", "title": "Version history, comments, developer handoff, redlines, and documentation"}, {"id": "81b1bf4b-7c43-49db-a378-d926a6b4be52", "type": "concept", "title": "Designing files for collaboration, reuse, and future maintenance"}], "description": "This section teaches professional workflow habits."}]}, {"id": "bbbbd647-75fd-43d5-a3de-0ac567a2b6ea", "type": "topic", "title": "Accessibility and Inclusive Web Design", "description": "Students design web experiences that can be used by people with varied abilities, devices, languages, and contexts.", "children": [{"id": "c771bdb7-da3c-414b-b6bb-daa18fea110b", "type": "subtopic", "title": "Accessibility foundations", "children": [{"id": "71973298-d49a-4ba0-9c68-b5526e8e2cf3", "type": "concept", "title": "WCAG principles: perceivable, operable, understandable, robust"}, {"id": "1502311f-5f19-418f-83bd-453fbdd46878", "type": "concept", "title": "Color contrast, text size, focus order, keyboard navigation, labels, alt text, captions, and forms"}, {"id": "2384b0eb-15f9-467e-aefe-a619aa49c26a", "type": "concept", "title": "Screen readers, zoom, reduced motion, high contrast, and assistive technologies"}], "description": "This subtopic covers the baseline expectations for inclusive digital interfaces."}, {"id": "8b499983-7b55-4078-9399-97c3569face9", "type": "subtopic", "title": "Inclusive interaction and content", "children": [{"id": "6cc8de33-8ed2-437d-a130-df25fd4f6fb9", "type": "concept", "title": "Plain language, clear labels, inclusive imagery, readable instructions, and helpful error messages"}, {"id": "b279b872-a6d9-404e-93e6-75a8a0e98abc", "type": "concept", "title": "Cognitive load, neurodiversity, localization, reading level, and cultural assumptions"}, {"id": "4f4d69d3-c805-471f-95d6-ca8e4aea5a7b", "type": "concept", "title": "Designing for stress, low bandwidth, older devices, and public-service contexts"}], "description": "Students learn that accessibility includes language, clarity, error recovery, and respect."}, {"id": "643f03cc-2571-4e9f-becd-cf23154a5ff0", "type": "subtopic", "title": "Evaluation and remediation", "children": [{"id": "0b5fdac8-ea78-47bc-8598-1327329d38c1", "type": "concept", "title": "Manual keyboard testing, screen reader spot checks, automated tools, contrast checks, and checklist reviews"}, {"id": "bb618402-0fdb-4e6d-92ad-9c163e325c1a", "type": "concept", "title": "Accessibility acceptance criteria, issue severity, and remediation priorities"}, {"id": "6b7902c2-35bb-4a73-9719-3b256acdd5b5", "type": "concept", "title": "Documenting decisions and limitations responsibly"}], "description": "This section introduces practical accessibility testing and repair."}]}, {"id": "3224c520-287e-463e-8815-1e5cdfb3fcbc", "type": "topic", "title": "Motion, Animation, and Microinteractions", "description": "Students use motion to clarify change, guide attention, express brand, and make interactions feel responsive.", "children": [{"id": "182a2582-eef1-44ab-b99c-59de00aa63a8", "type": "subtopic", "title": "Animation principles for UI", "children": [{"id": "aff1f268-4c6b-450c-9b52-f811d209053e", "type": "concept", "title": "Timing, easing, anticipation, follow-through, continuity, rhythm, and spatial logic"}, {"id": "9d4abe54-4551-49ea-b76e-97a6f73dd7b8", "type": "concept", "title": "Transitions, reveal, collapse, loading, confirmation, and feedback motion"}, {"id": "5c8e7ded-ce50-4ba1-8bc9-72916dba9124", "type": "concept", "title": "Motion as information, not distraction"}], "description": "This subtopic translates motion design fundamentals into interface behavior."}, {"id": "d8d84e75-269a-4159-b88b-127524800cd0", "type": "subtopic", "title": "Microinteraction design", "children": [{"id": "a564288d-97bb-47d4-9272-ebbd7df18ec7", "type": "concept", "title": "Triggers, rules, feedback, loops, and modes"}, {"id": "5d4f37fe-95db-400b-86ac-d75dba5d905b", "type": "concept", "title": "Button feedback, toggles, form validation, drag/drop, progress, notifications, and onboarding"}, {"id": "2e74aa21-32ff-4b31-9763-e8f3649b7377", "type": "concept", "title": "Delight, restraint, consistency, and user control"}], "description": "Students learn to design small moments that improve comprehension and confidence."}, {"id": "fcfe54c8-f801-4aef-b625-d8d973df01eb", "type": "subtopic", "title": "Accessible and performant motion", "children": [{"id": "2515f6f9-f113-4f34-884b-706997f5c0a8", "type": "concept", "title": "Reduced motion preferences, vestibular safety, cognitive load, and animation fatigue"}, {"id": "1b9c773e-d22c-4c68-b8e9-d1c8ede0c811", "type": "concept", "title": "Performance, frame rate, CSS transitions, Lottie, video, and file weight"}, {"id": "310703f4-ba3e-476e-b491-263231bdb22b", "type": "concept", "title": "Motion specs, handoff, and QA"}], "description": "This section keeps motion inclusive and technically responsible."}]}, {"id": "0d8113d1-f4bf-46f9-af95-bfffd8edbd24", "type": "topic", "title": "Design Systems, Components, and Web Product Consistency", "description": "Students build reusable components and rules that help teams ship coherent web experiences.", "children": [{"id": "ced7fb11-44a6-496e-b122-661f803d3146", "type": "subtopic", "title": "Design system foundations", "children": [{"id": "7ea4230a-0c23-4b38-abfe-18ce4e9bfaba", "type": "concept", "title": "Design tokens, colors, typography, spacing, grids, icons, components, patterns, and documentation"}, {"id": "a47e2294-12ad-4144-952d-3c13154ba820", "type": "concept", "title": "Consistency, flexibility, governance, contribution, and maintenance"}, {"id": "b0f42f36-9f92-4515-bee7-c9b7d70ecde6", "type": "concept", "title": "System maturity, adoption, and design debt"}], "description": "This subtopic teaches design systems as product infrastructure, not just style guides."}, {"id": "aefe3fe1-c4e1-4129-bbaa-c5698e76b807", "type": "subtopic", "title": "Component design", "children": [{"id": "37052e0b-2fb4-4b15-aff7-58fa5bc09757", "type": "concept", "title": "Buttons, inputs, cards, navigation, modals, tables, alerts, menus, and forms"}, {"id": "efed9398-e006-48ae-b2d5-5e7d7878e292", "type": "concept", "title": "States, variants, slots, responsive behavior, and interaction rules"}, {"id": "b0e28392-46f4-4406-ab46-40ee6d87df4a", "type": "concept", "title": "Content limits, error cases, accessibility notes, and usage examples"}], "description": "Students learn to design components with states, variants, content constraints, and accessibility built in."}, {"id": "384d5cf3-1978-4504-bc73-56510e465b6c", "type": "subtopic", "title": "Developer collaboration", "children": [{"id": "36385440-b2e9-48d3-a7ce-922f33369a47", "type": "concept", "title": "Figma libraries, Storybook, component specs, tokens, CSS variables, and handoff"}, {"id": "344bb408-4a53-42a1-8be3-0f1b0a2a9cdf", "type": "concept", "title": "Design-code parity, QA, naming, versioning, and release notes"}, {"id": "143c0a40-838c-4706-a683-7bfece66b6ca", "type": "concept", "title": "Negotiating tradeoffs between design intent and implementation constraints"}], "description": "This section connects design systems to implementation."}]}, {"id": "8419381c-6aea-41d0-be10-8908e3d594b7", "type": "topic", "title": "UX Writing, Content Strategy, and Microcopy", "description": "Students learn how words, labels, instructions, errors, and content structure shape the user experience.", "children": [{"id": "531e3753-82da-4d9f-973e-9e265e447d94", "type": "subtopic", "title": "Content strategy foundations", "children": [{"id": "f2174829-0079-4db4-9093-068f02b4918f", "type": "concept", "title": "Content audits, inventories, gap analysis, ownership, governance, and lifecycle"}, {"id": "c0dc097f-ef8b-4402-9731-4e92599fe9b7", "type": "concept", "title": "Voice, tone, messaging hierarchy, SEO/findability, and content operations"}, {"id": "81882cad-61a5-4e40-a538-6df7295cc951", "type": "concept", "title": "Content-first design and design-with-real-copy practice"}], "description": "This subtopic links content planning to user journeys and product governance."}, {"id": "f01c5088-e452-4f8a-ad0c-7aac1aca480f", "type": "subtopic", "title": "UX writing and microcopy", "children": [{"id": "43adb48e-21a5-451d-aeb9-adf38b084a9d", "type": "concept", "title": "Labels, button text, helper text, error messages, empty states, onboarding, confirmations, and alerts"}, {"id": "c8ed4eff-b5aa-4f70-a963-ab8b0eec801e", "type": "concept", "title": "Plain language, action verbs, specificity, tone, and reassurance"}, {"id": "86ee430c-b3a6-4f0b-86d3-1dcbbdc7faec", "type": "concept", "title": "Writing for accessibility, localization, and stress states"}], "description": "Students learn to write interface text that is clear, concise, helpful, and humane."}, {"id": "1ec8d043-ebb2-4441-84af-0cd5d1b83e97", "type": "subtopic", "title": "Content and IA integration", "children": [{"id": "eac59129-f838-4016-a6a4-b917be15ebee", "type": "concept", "title": "Taxonomies, page titles, metadata, search snippets, headings, and navigation labels"}, {"id": "760b5175-65c3-4a51-80ff-44af3bdfbd8a", "type": "concept", "title": "Content models, reusable modules, and structured content"}, {"id": "685973a9-3504-4c68-ae09-b73223c0c4f2", "type": "concept", "title": "Testing labels and copy through usability research"}], "description": "This section ties words to structure and navigation."}]}, {"id": "193c3f15-fcdc-427c-ac17-0f1e23f1b18c", "type": "topic", "title": "Usability Testing, Analytics, and Iteration", "description": "Students learn to evaluate interactive work with evidence and improve it through disciplined iteration.", "children": [{"id": "3a65936e-7918-49cc-9342-ff9111e5b4dc", "type": "subtopic", "title": "Usability testing methods", "children": [{"id": "23b9e169-8705-4553-a810-e6a7d4cb634f", "type": "concept", "title": "Moderated and unmoderated testing, think-aloud protocols, task scripts, and observation"}, {"id": "1ea8bb94-d1e6-4838-b983-910fed32d832", "type": "concept", "title": "Recruiting, consent, scenarios, success criteria, timing, errors, and confidence"}, {"id": "e2023870-a250-4fa9-b67d-bcceba4856ab", "type": "concept", "title": "Pilot tests, note-taking, synthesis, and issue severity"}], "description": "This subtopic teaches students to test whether people can actually use what they designed."}, {"id": "326a8939-6fb1-4ccc-8d41-1d248e859435", "type": "subtopic", "title": "Analytics and behavioral evidence", "children": [{"id": "b702dc55-a857-4dc3-ae4d-4b4a339d2979", "type": "concept", "title": "Funnels, events, conversions, scroll depth, search logs, heatmaps, A/B tests, and cohort behavior"}, {"id": "d4b3316f-ae62-4790-9e64-97c3bc379e41", "type": "concept", "title": "Metrics versus meaning, privacy, consent, and misuse of analytics"}, {"id": "e143d9ed-4cc4-4894-8950-4b96671ef9e9", "type": "concept", "title": "Triangulating analytics, research, support tickets, and stakeholder feedback"}], "description": "Students learn how product data can complement qualitative testing."}, {"id": "9c13bbe0-9696-4c3e-8b6c-c8933e2f2f74", "type": "subtopic", "title": "Iteration and prioritization", "children": [{"id": "f5c7f45c-6dfe-40a8-99ec-b40b9b10a33f", "type": "concept", "title": "Issue ranking, design hypotheses, revision plans, and acceptance criteria"}, {"id": "22c009f2-33a3-4ad4-9ac8-96a48bbee769", "type": "concept", "title": "Before/after evidence, change logs, versioning, and design rationale"}, {"id": "afdc0eb3-8f19-4c45-b2f2-4095b6111d4f", "type": "concept", "title": "Knowing when to refine, pivot, simplify, or ship"}], "description": "This section turns findings into better design decisions."}]}, {"id": "509dbb35-aa44-4b91-bf25-29e32615bde0", "type": "topic", "title": "Emerging Interfaces, AI, Social Computing, and Ethical Futures", "description": "Students examine how interactive design changes with AI, social platforms, ubiquitous computing, and new interface forms.", "children": [{"id": "af809c2e-9b97-43ed-bbfa-fde48f5dc2fb", "type": "subtopic", "title": "AI and adaptive interfaces", "children": [{"id": "494c1b2f-c859-4ad8-8021-0c3186bbe364", "type": "concept", "title": "AI assistants, recommendations, personalization, explainability, uncertainty, and user control"}, {"id": "fe6d9bbf-980b-40c4-98dc-df3c072129b7", "type": "concept", "title": "Prompting, hallucination, trust, feedback, correction, and escalation paths"}, {"id": "8396e168-aa7b-4b67-9d27-ee3f5f58c723", "type": "concept", "title": "Designing for transparency, consent, and human agency"}], "description": "This subtopic introduces design questions raised by generative, predictive, and personalized systems."}, {"id": "ca315520-aa94-40a3-a65b-5a07fc0a797a", "type": "subtopic", "title": "Social and ubiquitous computing", "children": [{"id": "656fb56e-ffab-4391-80f3-d8854c14a4f1", "type": "concept", "title": "Social platforms, communities, moderation, notifications, reputation, and sharing"}, {"id": "d2086467-2f3f-486d-9911-a71d1255c27e", "type": "concept", "title": "Mobile, wearable, voice, AR/VR, kiosk, ambient, and location-aware interfaces"}, {"id": "e18e2c4f-5922-4cb8-9703-cad7f78b7a90", "type": "concept", "title": "Privacy, surveillance, safety, harassment, and governance"}], "description": "Students consider interactions that happen across networks, places, devices, and communities."}, {"id": "d5d2884b-2425-4e46-91f5-f8a17b6ba923", "type": "subtopic", "title": "Ethical product decisions", "children": [{"id": "430e20f8-0747-428c-82ef-4982cf5b301f", "type": "concept", "title": "Dark patterns, persuasive design, addiction loops, data extraction, exclusion, and bias"}, {"id": "fbf7e27c-2662-4261-b164-0203eff754d8", "type": "concept", "title": "Privacy-by-design, accessibility-by-design, safety, and environmental impact"}, {"id": "26c58ef2-0e77-415a-ba82-d45f1cc07f37", "type": "concept", "title": "Ethics reviews, design principles, and accountability documentation"}], "description": "This section asks students to anticipate harms and responsibilities."}]}, {"id": "db61b603-7a71-4f6f-afb4-5eef9307f966", "type": "topic", "title": "Capstone: Responsive Interactive Product and Portfolio Case Study", "description": "Students synthesize research, IA, visual design, interaction, accessibility, prototyping, testing, and documentation in a polished web project.", "children": [{"id": "62fdc5d9-3ed3-45ac-9fb0-83793c12178c", "type": "subtopic", "title": "Project definition and research", "children": [{"id": "f072edee-6887-4dec-b182-3e1142ed6fb0", "type": "concept", "title": "Problem statement, audience, research plan, competitive audit, personas, journey map, and goals"}, {"id": "961d6592-1fe6-49d2-ab51-72451acedc03", "type": "concept", "title": "Content inventory, IA proposal, task flows, constraints, and success metrics"}, {"id": "60863023-64d2-4ce4-ab60-8a989ef97eb1", "type": "concept", "title": "Scope control, milestones, critique schedule, and risk list"}], "description": "The capstone begins with a bounded problem and evidence-based design direction."}, {"id": "96276303-72d1-43e1-89eb-8e2f28315ad0", "type": "subtopic", "title": "Design and build package", "children": [{"id": "a17e507a-9ba2-4fdc-90f8-61e61e5ea632", "type": "concept", "title": "Wireframes, responsive layouts, visual design, components, prototype, and optional HTML/CSS build"}, {"id": "2d3dfbd8-76a5-4176-9a13-039714f54177", "type": "concept", "title": "Accessibility checklist, interaction specs, content model, and design system notes"}, {"id": "32361ca1-69e7-4c1e-a89e-d8b4402dd7df", "type": "concept", "title": "Usability test, revisions, QA, and final presentation prototype"}], "description": "Students produce a coherent interactive experience and the documentation needed to evaluate it."}, {"id": "06b15732-4650-4107-9f92-7e2129f43933", "type": "subtopic", "title": "Portfolio case study", "children": [{"id": "6a573dca-497e-4343-85a9-fa0df23f295e", "type": "concept", "title": "Case study narrative, problem, process, evidence, decisions, iterations, and outcomes"}, {"id": "a1ce11c6-e6af-47b8-bd0d-33bf09a1ab92", "type": "concept", "title": "Screens, flows, prototype links, code link if applicable, and reflection"}, {"id": "6e9b036b-8a10-4d03-bb18-5fb5c8e324cd", "type": "concept", "title": "Design rationale, lessons learned, limitations, and next-step recommendations"}], "description": "This subtopic turns the final project into professional evidence of design thinking and craft."}]}], "dbBacked": true}$webinjson$::jsonb,
